import React from 'react';
import { Eye } from 'lucide-react';

const OrdersTable = () => {
  const [orders] = React.useState([
    { id: '#ORD-001', customer: 'John Smith', amount: '$450', status: 'delivered', date: '2024-01-15' },
    { id: '#ORD-002', customer: 'Emma Johnson', amount: '$320', status: 'processing', date: '2024-01-15' },
    { id: '#ORD-003', customer: 'Michael Brown', amount: '$890', status: 'shipped', date: '2024-01-14' },
    { id: '#ORD-004', customer: 'Sarah Wilson', amount: '$210', status: 'pending', date: '2024-01-14' },
  ]);

  const getStatusBadge = (status) => {
    switch (status) {
      case 'delivered':
        return { text: 'Livré', className: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' };
      case 'shipped':
        return { text: 'Expédié', className: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400' };
      case 'processing':
        return { text: 'En traitement', className: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400' };
      case 'pending':
        return { text: 'En attente', className: 'bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400' };
      default:
        return { text: 'Inconnu', className: 'bg-neutral-100 text-neutral-800 dark:bg-neutral-800 dark:text-neutral-400' };
    }
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl sm:rounded-2xl shadow-lg border border-white/30 dark:border-neutral-800/50 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-xs sm:text-sm">
          <thead>
            <tr className="border-b border-neutral-200 dark:border-neutral-700">
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap">ID Cmd</th>
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap">Client</th>
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap">Montant</th>
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap">Statut</th>
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap hidden sm:table-cell">Date</th>
              <th className="pb-2 sm:pb-3 px-2 sm:px-4 md:px-6 text-left text-xs font-medium text-neutral-600 dark:text-neutral-400 whitespace-nowrap">Action</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((order) => {
              const statusBadge = getStatusBadge(order.status);

              return (
                <tr key={order.id} className="border-b border-neutral-100 dark:border-neutral-800/50 last:border-0 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 transition-colors">
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6 font-medium text-primary-600 dark:text-primary-400 text-xs sm:text-sm whitespace-nowrap">{order.id}</td>
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6 font-medium text-neutral-900 dark:text-white text-xs sm:text-sm truncate">{order.customer}</td>
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6 font-medium text-neutral-900 dark:text-white text-xs sm:text-sm whitespace-nowrap">{order.amount}</td>
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6">
                    <span className={`inline-flex items-center px-2 sm:px-3 py-0.5 sm:py-1 rounded-full text-xs font-medium ${statusBadge.className}`}>
                      {statusBadge.text}
                    </span>
                  </td>
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6 text-neutral-600 dark:text-neutral-400 text-xs sm:text-sm whitespace-nowrap hidden sm:table-cell">{order.date}</td>
                  <td className="py-2 sm:py-4 px-2 sm:px-4 md:px-6">
                    <button className="flex items-center space-x-0.5 sm:space-x-2 px-2 sm:px-3 py-1 sm:py-1.5 rounded-lg bg-primary-50 dark:bg-primary-900/20 text-primary-600 dark:text-primary-400 hover:bg-primary-100 dark:hover:bg-primary-900/30 transition-colors">
                      <Eye className="h-3 w-3 sm:h-4 sm:w-4" />
                      <span className="hidden sm:inline text-xs sm:text-sm">Voir</span>
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default OrdersTable;
